export function throttle(fn: () => void, maxPerWindow: number, windowMs: number) {
  const timestamps = new Set<number>();
  const windowMsInt = Math.floor(windowMs);

  const wrapped = function () {
    const now = Date.now();
    const idx = timestamps.size;
    if (idx < maxPerWindow) {
      timestamps.add(now);
      fn();
    }
  };
  wrapped.reset = () => timestamps.clear();
  return wrapped;
}

// Self-test
const { throttle } = require('./throttle.ts');

console.log('Testing throttle...');

let passed = 0;
let failed = 0;

function assert(condition, msg) {
  if (condition) {
    console.log(`  ✓ ${msg}`);
    passed++;
  } else {
    console.error(`  ✗ ${msg}`);
    failed++;
  }
}

function makeHandler(fn) {
  const t = throttle(fn, 2, 50);
  t(); t(); t(); t(); // 5 calls, should call fn only twice
  assert(timestamps.size === 2, 'only called fn twice within 50ms');
}

// Simulate calls by using a closure that tracks invocations
let callCount = 0;
const handler = throttle(() => { callCount++; }, 2, 50);
handler();
handler();
handler();
handler();
handler();
assert(callCount === 2, 'maxPerWindow = 2, called only twice');

console.log(`\nResults: ${passed} passed, ${failed} failed`);
process.exit(failed > 0 ? 1 : 0);

