// throttle.ts — rate-limited function for Node.js
// Usage: node throttle.ts

export function throttle(fn: () => void, maxPerWindow: number, windowMs: number) {
  const timestamps = new Set<number>();
  const windowMsInt = Math.floor(windowMs);

  const wrapped = function () {
    const now = Date.now();
    const idx = timestamps.size;
    if (idx < maxPerWindow) {
      timestamps.add(now);
      fn();
    }
  };
  wrapped.reset = () => timestamps.clear();
  return wrapped;
}

// Self-test
console.log('Testing throttle...');

let passed = 0;
let failed = 0;

function assert(condition, msg) {
  if (condition) {
    console.log(`  ✓ ${msg}`);
    passed++;
  } else {
    console.error(`  ✗ ${msg}`);
    failed++;
  }
}

// Test 1: maxPerWindow = 2, 5 calls → fn called only twice
let callCount = 0;
const handler = throttle(() => { callCount++; }, 2, 50);
handler(); handler(); handler(); handler(); handler();
assert(callCount === 2, 'maxPerWindow = 2, called fn only twice');

// Test 2: reset clears the window
handler.reset();
